<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Support\Facades\Storage; class ProductImage extends Model { protected $guarded = []; public function product() { return $this->belongsTo(Product::class); } public function getImageUrlAttribute() { if (!$this->image_path) return null; return str_starts_with($this->image_path, 'http') ? $this->image_path : Storage::url($this->image_path); } }